CREATE TABLE tenants(id uuid PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants,username text UNIQUE NOT NULL,password_hash text,role text NOT NULL CHECK(role IN ('customer','operator')),disabled boolean NOT NULL DEFAULT false,totp_secret text,last_totp_step bigint NOT NULL DEFAULT -1,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users,csrf text NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE account_tokens(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users,expires_at timestamptz NOT NULL,used_at timestamptz);
CREATE TABLE login_attempts(username text PRIMARY KEY,attempts integer NOT NULL DEFAULT 0,window_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE settings(id integer PRIMARY KEY CHECK(id=1),unit_price bigint NOT NULL CHECK(unit_price>0),capacity integer NOT NULL CHECK(capacity BETWEEN 0 AND 30));
INSERT INTO settings VALUES(1,1000,0);
CREATE TABLE wallets(tenant_id uuid PRIMARY KEY REFERENCES tenants,balance bigint NOT NULL DEFAULT 0 CHECK(balance>=0));
CREATE TABLE ledger(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants,amount bigint NOT NULL CHECK(amount<>0),kind text NOT NULL,reference text NOT NULL,idempotency_key text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,idempotency_key));
CREATE FUNCTION immutable_ledger() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'ledger is immutable'; END $$;
CREATE TRIGGER ledger_immutable BEFORE UPDATE OR DELETE ON ledger FOR EACH ROW EXECUTE FUNCTION immutable_ledger();
CREATE TABLE topups(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants,amount bigint NOT NULL CHECK(amount>0),status text NOT NULL DEFAULT 'pending',bank_reference text UNIQUE,actual_amount bigint,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE quotes(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants,kind text NOT NULL CHECK(kind IN ('purchase','renew')),quantity integer NOT NULL CHECK(quantity BETWEEN 1 AND 30),days integer NOT NULL CHECK(days BETWEEN 1 AND 365),slot_ids uuid[] NOT NULL DEFAULT '{}',unit_price bigint NOT NULL,total bigint NOT NULL CHECK(total>0),expires_at timestamptz NOT NULL,consumed_at timestamptz);
CREATE TABLE orders(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants,quote_id uuid NOT NULL UNIQUE REFERENCES quotes,idempotency_key text NOT NULL,total bigint NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE slots(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants,label text NOT NULL DEFAULT 'Bot của tôi',status text NOT NULL DEFAULT 'awaiting_activation',purchased_days integer NOT NULL,purchase_amount bigint NOT NULL,activation_deadline timestamptz NOT NULL,activated_at timestamptz,expires_at timestamptz,binding_revision bigint NOT NULL DEFAULT 0,zalo_uid text,config jsonb NOT NULL DEFAULT '{}',config_revision bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX slots_uid_bound ON slots(zalo_uid) WHERE zalo_uid IS NOT NULL AND status NOT IN ('refunded','purged');
CREATE FUNCTION portal_used_capacity() RETURNS bigint LANGUAGE sql SECURITY DEFINER SET search_path=public SET row_security=off AS $$ SELECT count(*) FROM slots WHERE (activated_at IS NULL AND status NOT IN ('refunded','purged')) OR expires_at>now() $$;
CREATE TABLE operations(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants,slot_id uuid REFERENCES slots,kind text NOT NULL,status text NOT NULL DEFAULT 'pending',payload jsonb NOT NULL DEFAULT '{}',result jsonb,binding_revision bigint NOT NULL DEFAULT 0,attempts integer NOT NULL DEFAULT 0,lease_until timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX operations_queue ON operations(status,created_at);
CREATE TABLE campaigns(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants,slot_id uuid NOT NULL REFERENCES slots,binding_revision bigint NOT NULL,kind text NOT NULL CHECK(kind IN ('group','dm')),status text NOT NULL DEFAULT 'draft',content jsonb NOT NULL,schedule jsonb NOT NULL DEFAULT '{}',recipients jsonb NOT NULL DEFAULT '[]',exclusions jsonb NOT NULL DEFAULT '[]',revision bigint NOT NULL DEFAULT 0,next_run_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE campaign_runs(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants,campaign_id uuid NOT NULL REFERENCES campaigns,status text NOT NULL DEFAULT 'pending',scheduled_at timestamptz NOT NULL DEFAULT now(),started_at timestamptz,finished_at timestamptz,UNIQUE(campaign_id,scheduled_at));
CREATE UNIQUE INDEX campaign_run_active ON campaign_runs(campaign_id) WHERE status IN ('pending','running');
CREATE TABLE deliveries(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants,run_id uuid NOT NULL REFERENCES campaign_runs,slot_id uuid NOT NULL REFERENCES slots,binding_revision bigint NOT NULL,recipient text NOT NULL,status text NOT NULL DEFAULT 'pending',result jsonb,lease_until timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(run_id,recipient));
CREATE TABLE rosters(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants,slot_id uuid NOT NULL REFERENCES slots,binding_revision bigint NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE uploads(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants,mime text NOT NULL,data bytea NOT NULL CHECK(octet_length(data)<=10485760),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants,kind text NOT NULL,body jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants,actor_id uuid,action text NOT NULL,resource_id uuid,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION portal_tenant() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('portal.tenant_id',true),'')::uuid $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['wallets','ledger','topups','quotes','orders','slots','operations','campaigns','campaign_runs','deliveries','rosters','uploads','notifications','audit'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t); EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (tenant_id=portal_tenant()) WITH CHECK (tenant_id=portal_tenant())',t); END LOOP; END $$;
